---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Sign in: Email first, then the one-time code from the email, copied or typed in.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change sign-in.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './sign-in.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="sign-in" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="sgx panel">
  <div class="sgx-body">
  <div class="sgx-st sgx-1">
    <b>Sign in</b><span class="muted">We will email you a code</span>
    <label class="sgx-f"><span>Email</span><input type="email" class="sgx-em" placeholder="you@studio.com" autocomplete="off"></label>
    <div class="fold shut sgx-ef"><div><span class="sgx-err" aria-live="polite"></span></div></div>
  </div>
  <div class="sgx-st sgx-2" hidden>
    <button class="sgx-bk"><svg class="i xs"><use href="#i-chev-l"/></svg><span class="sgx-to"></span></button>
    <b>Check your inbox</b><span class="muted">Enter the 6 digit code</span>
    <div class="sgx-code" role="group" aria-label="Code"></div>
    <div class="fold shut sgx-af"><div><button class="chip sgx-sug" type="button" aria-label="Fill in the code from Mail, 482 157"><svg class="i xs"><use href="#i-mail"/></svg><span>From Mail</span><span class="num">482 157</span></button></div></div>
  </div>
  </div>
  <div class="sgx-ft">
    <button class="pill primary sgx-go">Send code</button>
    <span class="muted sgx-rs" aria-live="polite" hidden></span>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './sign-in.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Sign in ---------- */
/* its content 16px in from every edge (owner, 18 Nov). The card grows and shrinks with each step, so it keeps no room for a
   later one: the code arriving, a message under the field, the shorter confirmation. The steps (.sgx-body) and the foot each
   ease their own height (grow()), and the card is always the two together: the foot stays at the card's bottom edge with its
   corners at every frame, and only the steps are clipped while they ease, top to bottom (owner, 21 Nov). The title block, the
   boxes and the line under them are 12px apart */
.sgx{padding:var(--dm-s-4);max-width:320px;margin:0 auto;width:100%}
.sgx-body.growing{overflow-x:visible}
.sgx-st{display:flex;flex-direction:column;gap:6px}
.sgx-st>b{font-weight:500;font-size:14px}
.sgx-st>.muted{font-size:12.5px;margin-bottom:6px}
.sgx-st.in{animation:sgin .5s var(--dm-ease) both}
@keyframes sgin{from{opacity:0;transform:translateX(20px);filter:blur(4px)}}
.sgx-f{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500}
.sgx-f input{height:var(--dm-field-h);border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:0 var(--dm-s-3);font:inherit;font-size:13.5px;font-weight:400;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.sgx-f input{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.sgx-f input::placeholder{color:var(--dm-muted)}
.sgx-f input:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* a field marked wrong keeps its red edge, focused or not, until it is fixed; the line under it says what is wrong in red
   words after the alert mark, with no red fill, and opens and closes rather than keeping room for itself */
.sgx-f.bad input{box-shadow:inset 0 0 0 1px var(--dm-bad);animation:sgsh .4s}
@keyframes sgsh{20%,60%{transform:translateX(-4px)}40%,80%{transform:translateX(4px)}}
/* (a shut line adds nothing under the field: the fold takes back the step's 6px gap, and the open line brings its own) */
.sgx-ef{margin-top:-6px}
.sgx-err{display:flex;align-items:center;gap:6px;padding-top:6px;font-size:12px;color:var(--dm-bad)}
.sgx-err>svg{flex:none;color:var(--dm-bad-mark,var(--dm-bad))}
/* nothing in it grows or shrinks when pressed but Clean's ink primary */
.sgx .pill:active{transform:none}
/* the foot: the step's action or the line that says how it is going (Send code, then the resend line, Verifying code, a
   wrong code or Code confirmed, then the workspace opening). It is one foot for every step, so it keeps its place as the
   steps change: 12px under the step in Soft and Blueprint, and Clean's foot strip (below). Send code is as wide as the field */
.sgx-ft{margin-top:var(--dm-s-3)}
.sgx-go{height:var(--dm-field-h);width:100%}
/* the back link's chevron sits on the content's edge, as the words under it do */
.sgx-bk{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--dm-muted);align-self:flex-start;margin:0 0 6px -4px}
@media (hover:hover) and (pointer:fine){.sgx-bk:hover{color:var(--dm-fg)}}
.sgx-code{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
/* the boxes: every box, filled or not, has the one fill and the one dimmed edge; the focused box, or with none focused the
   next one to fill, has the field's focus edge. While the code is checked all six dim a little, together, and the line under
   them says so (owner, 21 Nov: no wave across them) */
.sgx-code input{width:100%;height:var(--dm-field-h);border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);text-align:center;font:inherit;font-size:14px;font-variant-numeric:tabular-nums;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast),opacity var(--dm-t-fast),transform .3s var(--dm-ease)}
@supports (corner-shape:squircle){.sgx-code input{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.sgx-code input:focus,.sgx-code:not(:focus-within) input.nx{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.sgx-code input.f{transform:scale(1.04)}
/* the code as it arrives (owner, 21 Nov: no card in the card): a quiet chip under the boxes, the way a phone offers a
   one-time code, "From Mail 482 157". Pressed, it fills every box and goes. It folds open when the email arrives, so the card
   grows smoothly for it and keeps no room before */
.sgx-af{margin-top:-6px}
.sgx-sug{display:flex;width:fit-content;margin-top:var(--dm-s-3)}
.sgx-sug .num{color:var(--dm-fg);font-weight:500}
.sgx-code input{caret-color:var(--dm-accent-fg,var(--dm-accent))}
.sgx-code.vf input{opacity:.7}
/* a wrong code: the boxes clear with a red edge and shake (not with reduced motion) until typing starts over */
.sgx-code.bad input{box-shadow:inset 0 0 0 1px var(--dm-bad)}
.sgx-code.bad{animation:sgsh .4s}
@media (prefers-reduced-motion:reduce){.sgx-code.bad,.sgx-f.bad input{animation:none}}
/* the line under the boxes: what runs is said with the highlight sweep; a confirmed code is the green tick and plain words */
.sgx-v{display:inline-flex;align-items:center;gap:7px;color:var(--dm-fg2)}
.sgx-rs>.sgx-v{display:flex;min-height:inherit}
.sgx-v .spin{width:11px;height:11px}
.sgx-v .shim{font-size:inherit}
.sgx-v.ok .i{color:var(--dm-ok-mark)}
.sgx-v.bad{color:var(--dm-bad)}
.sgx-v.bad .i{color:var(--dm-bad-mark,var(--dm-bad))}
.sgx-hint{color:var(--dm-fg2)}
.sgx-re{color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;font-size:inherit;border-radius:var(--dm-r-tiny,4px)}
@media (hover:hover) and (pointer:fine){.sgx-re:hover{text-decoration:underline;text-underline-offset:2px}}
.sgx-ck{width:52px;height:52px;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}
.sgx-ck circle{stroke:var(--dm-ok-mark);stroke-dasharray:151;stroke-dashoffset:151;animation:sgdraw .7s var(--dm-ease) forwards}
.sgx-ck path{stroke:var(--dm-ok-mark);stroke-dasharray:30;stroke-dashoffset:30;animation:sgdraw .4s var(--dm-ease) .55s forwards}
@keyframes sgdraw{to{stroke-dashoffset:0}}
.sgx-bar{width:120px;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);overflow:hidden;margin-top:var(--dm-s-1)}
.sgx-bar i{display:block;height:100%;width:0;background:var(--dm-accent-mark,var(--dm-accent));animation:sgbar 1.8s var(--dm-ease) .6s forwards}
@keyframes sgbar{to{width:100%}}
.sgx-rs{display:block;min-height:20px;font-size:12px;line-height:20px}
.sgx-ft :is(.sgx-go,.sgx-rs)[hidden]{display:none}
/* done: the green check and the welcome, and in the foot the workspace opening */
.sgx-done{display:flex;flex-direction:column;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-4) 0 0;font-size:13px;text-align:center}
.sgx-done>b{font-weight:500;font-size:14px}
.sgx-open{display:flex;flex-direction:column;align-items:center;gap:var(--dm-s-2);padding-bottom:var(--dm-s-4);font-size:13px}
.sgx-open .shim{font-size:inherit}
/* Clean: the steps rise into place without a blur. The foot is the card's off-white foot strip in every step (owner, 21 Nov:
   "this has no clean style separation"): a top hairline, the card's bottom corners, its contents on the 16px column, 8px from
   its top and bottom. The fields stay in the body, 16px above it */
:root[data-style="clean"] .sgx-st.in,:root [data-style="clean"] .sgx-st.in,:root [data-style="clean"].sgx-st.in{animation:clpiece var(--dm-t-slow) var(--dm-ease) both}
:root[data-style="clean"] .sgx-ft,:root [data-style="clean"] .sgx-ft,:root [data-style="clean"].sgx-ft{margin:var(--dm-s-4) calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4));padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .sgx-rs,:root [data-style="clean"] .sgx-rs,:root [data-style="clean"].sgx-rs{min-height:28px;line-height:28px}
:root[data-style="clean"] .sgx-done,:root [data-style="clean"] .sgx-done,:root [data-style="clean"].sgx-done{padding-top:0}
:root[data-style="clean"] .sgx-open,:root [data-style="clean"] .sgx-open,:root [data-style="clean"].sgx-open{padding-bottom:0}
:root[data-style="clean"] .sgx-sug,:root [data-style="clean"] .sgx-sug,:root [data-style="clean"].sgx-sug{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .sgx-sug:hover,:root [data-style="clean"] .sgx-sug:hover,:root [data-style="clean"].sgx-sug:hover{background:var(--dm-chip);box-shadow:inset 0 0 0 99px var(--dm-row)}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, grow, html, stagger, swap } from '../core/core.js';
DM.def('sign-in', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{l}', I('chev-l','xs')).replace('{mail}', I('mail','xs'));
  const card = $('.sgx', r), body = $('.sgx-body', r), af = $('.sgx-af', r), sug = $('.sgx-sug', r), s1 = $('.sgx-1', r), s2 = $('.sgx-2', r), ft = $('.sgx-ft', r), em = $('.sgx-em', r), ef = $('.sgx-ef', r), err = $('.sgx-err', r), go = $('.sgx-go', r), rs = $('.sgx-rs', r), code = $('.sgx-code', r);
  code.innerHTML = Array.from({ length:6 }, (_, i) => `<input inputmode="numeric" maxlength="1" autocomplete="${i ? 'off' : 'one-time-code'}" aria-label="Digit ${i + 1}">`).join('');
  const CODE = '482157';
  const ins = $$('input', code);
  // the card fits each step at every moment (grow(), never a kept height): the code arriving, a message under the field and
  // the shorter confirmation all ease the steps to their height, and the foot eases to its own, so the card, which is the two
  // together, eases with them and its foot never leaves its bottom edge. It starts once the card's entrance has ended
  Promise.resolve().then(() => Promise.all(card.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && card.isConnected){ c.offs.push(grow(body)); c.offs.push(grow(ft)); } });
  // what is wrong with the email, in red words after the alert mark; the line opens under the field and closes again, so no
  // room is kept for it
  const say = t => {
    if (!t){ ef.classList.add('shut'); return; }
    const s = $('span', err);
    if (s && !ef.classList.contains('shut')) swap(s, t); else err.innerHTML = I('alert','xs') + `<span>${t}</span>`;
    ef.classList.remove('shut');
  };
  // where the code stands: idle (typing), vf (being checked), bad (wrong, until typing starts over) or ok
  let st = 'idle', n = 30, iv = 0;
  // with no box focused, the next one to fill has the focus edge
  const next = () => { const k = st === 'idle' ? ins.findIndex(i => !i.value) : -1; ins.forEach((i, j) => i.classList.toggle('nx', j === k)); };
  // the line under the boxes, while the code is being typed: the resend countdown, then Resend code. What the foot says
  // changes in place, with no fade, so the foot is never empty for a moment
  const idle = () => { if (st !== 'idle') return;
    if (n > 0){ rs.innerHTML = `Resend in <span class="num">${n}</span>s`; return; }
    rs.innerHTML = '<button class="sgx-re">Resend code</button>'; $('.sgx-re', rs).onclick = () => { n = 30; idle(); }; };
  const send = demo => c.run(async () => {
    const v = em.value.trim();
    if (!/^\S+@\S+\.\S+$/.test(v)){ const f = em.parentElement; f.classList.remove('bad'); void f.offsetWidth; f.classList.add('bad'); em.setAttribute('aria-invalid', 'true'); say(v ? 'That email looks incomplete' : 'Enter your email'); return; }
    em.parentElement.classList.remove('bad'); em.removeAttribute('aria-invalid'); say(''); go.innerHTML = '<span class="spin"></span>'; await c.wait(800);
    s1.hidden = true; s2.hidden = false; s2.classList.remove('in'); void s2.offsetWidth; s2.classList.add('in'); $('.sgx-to', r).textContent = v;
    // the foot swaps Send code for the resend line, in the same place
    go.hidden = true; rs.hidden = false; st = 'idle'; n = 30; idle(); next();
    if (demo !== true && c.mine) ins[0].focus({ preventScroll:true });
    // the email arrives: its code is offered under the boxes, the way a phone offers a one-time code
    c.later(900, () => { if (st !== 'ok') af.classList.remove('shut'); });
    clearInterval(iv); iv = c.every(1000, () => { if (st === 'ok' || n <= 0 || s2.hidden) return; n--; idle(); });
  });
  go.onclick = () => send(); em.onkeydown = e => { if (e.key === 'Enter') send(); };
  // a wrong code stays marked until typing starts over
  const fresh = () => { if (st !== 'bad') return; st = 'idle'; code.classList.remove('bad'); ins.forEach(i => i.removeAttribute('aria-invalid')); idle(); };
  $('.sgx-bk', r).onclick = () => { if (st === 'vf' || st === 'ok') return; fresh(); clearInterval(iv); af.classList.add('shut'); ins.forEach(i => i.value = '');
    s2.hidden = true; s1.hidden = false; s1.classList.remove('in'); void s1.offsetWidth; s1.classList.add('in'); rs.hidden = true; go.hidden = false; go.textContent = 'Send code'; };
  // the code is checked once every box is filled: the boxes dim a little while the line says Verifying code; a wrong one
  // clears them with a red edge and a shake and says so in red; the right one gets the green tick, then the welcome
  function check(){ if (st !== 'idle' || !ins.every(i => i.value)) return; st = 'vf'; next(); c.run(async () => {
    ins.forEach(i => { i.blur(); i.readOnly = true; });
    code.classList.add('vf'); rs.innerHTML = '<span class="sgx-v"><span class="spin"></span><span class="shim">Verifying code</span></span>'; await c.wait(1100);
    code.classList.remove('vf'); ins.forEach(i => i.readOnly = false);
    if (ins.map(i => i.value).join('') !== CODE){
      st = 'bad'; ins.forEach(i => { i.value = ''; i.setAttribute('aria-invalid', 'true'); });
      code.classList.remove('bad'); void code.offsetWidth; code.classList.add('bad');
      rs.innerHTML = `<span class="sgx-v bad">${I('alert','xs')}That code didn't work, try again</span>`;
      if (c.mine) ins[0].focus({ preventScroll:true });
      return;
    }
    st = 'ok'; ins.forEach(i => i.readOnly = true); af.classList.add('shut');
    rs.innerHTML = `<span class="sgx-v ok">${I('check','xs')}Code confirmed</span>`; await c.wait(1100);
    // the welcome takes the steps' place, and the foot carries the workspace opening in the same moment, so it is never empty
    s1.hidden = true; s2.hidden = true; rs.hidden = true;
    const d = html(`<div class="sgx-done" role="status"><svg class="sgx-ck" viewBox="0 0 52 52" aria-hidden="true"><circle cx="26" cy="26" r="24"/><path d="m16 27 7 7 13-14"/></svg><b>You're in</b></div>`);
    const op = html('<span class="sgx-open"><span class="shim">Opening your workspace</span><span class="sgx-bar"><i></i></span></span>');
    ($(':scope>.dm-grow', body) || body).appendChild(d); ($(':scope>.dm-grow', ft) || ft).appendChild(op); stagger([d.lastChild], 90, 250); }); }
  // a pasted code, or the one Mail offers, fills every box from the first
  const paste = t => { t = t.replace(/\D/g, '').slice(0, 6); if (!t || st === 'vf' || st === 'ok') return; fresh(); ins.forEach((i, j) => { i.value = t[j] || ''; }); next(); if (c.mine && t.length < 6) ins[t.length].focus({ preventScroll:true }); check(); };
  sug.onclick = () => { if (st === 'vf' || st === 'ok') return; af.classList.add('shut'); paste(CODE); };
  ins.forEach((i, k) => {
    i.oninput = () => { fresh(); i.value = i.value.replace(/\D/g, '').slice(-1); if (i.value && ins[k + 1]) ins[k + 1].focus({ preventScroll:true }); next(); check(); };
    i.onkeydown = e => { if (e.key === 'Backspace' && !i.value && ins[k - 1]){ ins[k - 1].focus({ preventScroll:true }); ins[k - 1].value = ''; next(); } };
    i.onpaste = e => { const t = (e.clipboardData.getData('text') || '').replace(/\D/g, ''); if (!t) return; e.preventDefault(); paste(t); };
  });
  // the preview's story: type an email and send it; the code arrives and Mail offers it; type it from memory with two digits
  // swapped, see it fail, then take the one Mail offers. The visitor can take over at any point and go through it with their
  // own email, typing 482 157 or pressing the chip
  c.story(async s => {
    await s.beat(2); await s.tap(em); await s.type(em, 'maya@studio.com', { n:.08 });
    await s.beat(1); await s.tap(go); s.away();
    await s.until(() => !af.classList.contains('shut')); await s.beat(2);
    for (const [j, d] of [...'482175'].entries()){ fresh(); ins[j].value = d; next(); await s.beat(.5); }
    check(); await s.until(() => st === 'bad'); await s.beat(4);
    await s.tap(sug); s.away();
    await s.until(() => !!$('.sgx-done', r)); await s.beat(4);
  });
});
